use super::*;

/// Mark every id in `doc` as exported at its CURRENT main head — the files and the ledger now agree.
///
/// Called from exactly two places, and the distinction is load-bearing: after the export WRITES the
/// files, and after `store import --refresh` adopts the files into the ledger. Both end with the two
/// sides equal, which is the only moment a watermark is true.
///
/// [`sync_document`] deliberately does NOT call this, even though it looks like the same shape:
/// `save()` reaches it on every `impl set`, where the document is the graph in MEMORY and the files
/// have not moved at all. Marking there would claim the files matched a body they have never held, and
/// [`export_drift`] would then report every `impl set` as a file-side edit — the exact inversion of
/// what it is for.
pub fn mark_document_exported(conn: &Connection, doc: &Value) -> Result<usize, String> {
    let mut n = 0;
    for key in ["implementations", "edges"] {
        for rec in doc.get(key).and_then(Value::as_array).map(Vec::as_slice).unwrap_or(&[]) {
            let Some(id) = rec.get("id").and_then(Value::as_str) else { continue };
            // At the rev whose body the file actually HOLDS — not blindly at head. After an export or
            // a refresh those are the same thing. On a ledger another session has written past they
            // are not, and marking at head would claim the file matched a body it has never held,
            // which reads back as a file-side edit on the very next export.
            let body = import::body_of(rec);
            if let Some(rev) = rev_holding(conn, id, &body)? {
                mark_exported(conn, id, rev)?;
                n += 1;
            }
        }
    }
    Ok(n)
}
